'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var Float64Array = require( '@stdlib/array/float64' );
var rffti = require( '@stdlib/fft/base/fftpack/rffti' );
var pkg = require( './../package.json' ).name;
var rfftf = require( './../lib' );


// VARIABLES //

var options = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} N - sequence length to transform
* @returns {Function} benchmark function
*/
function createBenchmark( N ) {
	var workspace;
	var r;
	var c;

	workspace = new Float64Array( ( 2*N ) + 34 );
	rffti( N, workspace, 1, 0 );

	r = uniform( N, -10.0, 10.0, options );
	c = new Float64Array( N );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var i;
		var j;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			/*
			* Copy the original input array before each transformation. This is necessary because `rfftf` modifies the input array in-place, and applying the forward FFT repeatedly to already-transformed data causes values to grow unbounded and eventually overflow to NaN.
			*/
			for ( j = 0; j < N; j++ ) {
				c[ j ] = r[ j ];
			}
			rfftf( N, c, 1, 0, workspace, 1, 0 );
			if ( isnan( c[ i%N ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();

		if ( isnan( c[ i%N ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var lengths;
	var N;
	var f;
	var i;

	lengths = [
		8,
		16,
		32,
		64,
		128,
		256
	];

	for ( i = 0; i < lengths.length; i++ ) {
		N = lengths[ i ];
		f = createBenchmark( N );
		bench( pkg+':N='+N, f );
	}
}

main();
